<?php
require_once __DIR__.'/includes/registry.php';require_once __DIR__.'/../includes/functions.php';
$key=$_SERVER['OHSC_EDITORIAL_PAGE'];$ohsc_tool_meta=ohsc_tool_seo_init($db,$key,$base_url);$ohsc_resource_meta=true;
$conditions=array('career-guides'=>"(title LIKE '%career%' OR title LIKE '%how to become%')",'career-advice'=>"(title LIKE '%career%' OR title LIKE '%job%' OR title LIKE '%interview%')",'cv-and-cover-letters'=>"(title LIKE '%CV%' OR title LIKE '%cover letter%' OR title LIKE '%resume%')");
$articles=$db->query("SELECT title,slug,image,excerpt FROM blog WHERE status=1 AND slug<>'' AND ".$conditions[$key]." ORDER BY publish_date DESC LIMIT 40")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><?php ohsc_tool_seo_head($ohsc_tool_meta);include __DIR__.'/../includes/header-home-new.php'; ?><link rel="stylesheet" href="<?php echo ohsc_h($base_url); ?>/tools/assets/resources.css?v=7"><main class="career-resources"><div class="resource-wrap"><section class="resource-panel"><h1><?php echo ohsc_h($ohsc_tool_meta['title']); ?></h1><p>Explore practical guidance for your next career step.</p><div class="resource-goals"><?php foreach ($articles as $article) { ?><a href="<?php echo ohsc_h(rtrim($base_url,'/').'/OHSC-Blog/'.rawurlencode($article['slug'])); ?>"><div><?php if ($article['image']) { ?><img style="width:100%;max-height:180px;object-fit:cover;border-radius:12px" src="<?php echo ohsc_h(rtrim($base_url,'/').'/images/blog/'.rawurlencode(basename($article['image']))); ?>" alt=""><?php } ?><h2><?php echo ohsc_h(strip_tags($article['title'])); ?></h2><p><?php echo ohsc_h(strip_tags($article['excerpt'])); ?></p></div><span>→</span></a><?php } ?></div></section></div></main><?php include __DIR__.'/../includes/footer-new.php'; ?></html>
